var colors1 = "e466f9-e126a0-bef838-c294e2-cdb5a3"
  .split("-")
  .map((a) => "#" + a);

function setup() {
  frameRate(1);
  pixelDensity(5);
  createCanvas(windowWidth, windowHeight);
  background(0);
}

function draw() {
  background(0);  
  push();
  translate(width / 2, height / 2);
  let totalScale = 1.25;
  let d =6;
  // 要素dによって　複雑さ　大きほど大きければ複雑になる 
  divAng(0, max(width, height) * totalScale, 0, PI * 2, d); 
  //main functionを使う
  pop();
  noLoop();
}

//functionを作る
// stR/edR arcの半径のスタート・エンド
// stAng/edAng arcの角度のスタート・エンド
function divAng(stR, edR, stAng, edAng, d, colors) {　   
  push();  
  rotate(random(-2.5, 2.5));
  let ww = pow(edR - stR, 1.25 - d / 4) * random(0,0.2);
  let cc = random(colors1);
  fill(cc);
  //strokeWeight(ww);
  //strokeCap(SQUARE);
  //noFill();
  arc(0, 0, stR, stR, stAng, edAng);

  let ratio = random();
  if (d > 0) {
    if (random() < 0.90) {
      let splitNum = int(random(6,10)); //　分裂や割目のコントロール
      for (let i = 1; i <= splitNum; i++) {
        divAng(
          stR,
          edR,
          stAng + ((i - 1) * (edAng - stAng)) / splitNum,
          stAng + (i * (edAng - stAng)) / splitNum,
          d - 1
        );
      }
    } else {
      divAng(stR, stR + ratio * (edR - stR), stAng, edAng, d - 1);
      divAng(stR + ratio * (edR - stR), edR, stAng, edAng, d - 1);
    }
  }  
  pop();
}



function mouseClicked() {
  loop();
}

